Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>

#define mkp make_pair
#define psh push_back
#define ll long long

using namespace std;

const int MOD = 1000000007;

int parent_array[1111111];
int total_components;

int find_parent(int x) {
    if (x == parent_array[x]) return x;
    return parent_array[x] = find_parent(parent_array[x]);
}

void union_sets(int a, int b) {
    a = find_parent(a);
    b = find_parent(b);
    if (a == b) return;
    total_components--;
    parent_array[b] = a;
}

ll mod_pow(ll base, int e) {
    if (e == 0) return 1;
    ll half = mod_pow(base, e / 2);
    ll res = (half * half) % MOD;
    if (e & 1) res = (res * base) % MOD;
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << mod_pow(p, p - 1) << '\n';
        return 0;
    }

    total_components = p - (k > 1);
    for (ll i = 1; i < p; i++) parent_array[i] = i;

    for (ll i = 1; i < p; i++) {
        union_sets(i, (i * k) % p);
    }

    cout << mod_pow(p, total_components) << '\n';

    return 0;
}
